// Create the object; ownership is transferred to the fuzzer runtime via output varset.
modsecurity::AnchoredSetVariable *varset = new modsecurity::AnchoredSetVariable(t, name);

// Track attributes helpful for later stubs (name association and an entry count heuristic).
FUZZ_SET_ATTR_STR(varset, "name", name.c_str());
