import os
import random
import string
from typing import List

# Generator for filesystem path string buffers suitable for FUZZ_PARAM_FILENAME/FUZZ_PARAM_STR
# We return bytes containing a NUL-terminated path-like string or a plain path string.
# The harness treats FUZZ_PARAM_FILENAME as a filename pointing to random fuzzable data,
# so we should emit plausible, valid path strings that may reference files or directories.

SAFE_CHARS = string.ascii_letters + string.digits + "-_."
PATH_SEPARATORS = ["/", os.sep]

# Some interesting directory components
DIR_NAMES = [
    "tmp", "var", "log", "modsec", "audit", "..", ".", "etc", "home",
    "data", "cache", "." * 1, ".." * 1
]

FILE_BASENAMES = [
    "audit.log", "audit.json", "rules.conf", "unicode.map", "body.bin",
    "requests.dat", "responses.dat", "index", "A", "Z", "part-C", "entry.K", "00000000"
]

EXTS = ["", ".log", ".json", ".conf", ".txt", ".dat"]

PREFIXES = [
    "/",  # absolute POSIX
    "",   # relative
]

# Windows-like absolute patterns (only as strings; runtime may ignore on non-Windows)
WIN_DRIVES = [f"{c}:\\" for c in "CDE"]


def _rand_name(r: random.Random, min_len=1, max_len=12) -> str:
    n = r.randint(min_len, max_len)
    return "".join(r.choice(SAFE_CHARS) for _ in range(n))


def _rand_component(r: random.Random) -> str:
    # Occasionally choose special names
    if r.random() < 0.4:
        return r.choice(DIR_NAMES)
    return _rand_name(r)


def _maybe_ext(r: random.Random) -> str:
    ext = r.choice(EXTS)
    if ext:
        return ext
    # sometimes none
    return ""


def _rand_filename(r: random.Random) -> str:
    if r.random() < 0.5:
        base = r.choice(FILE_BASENAMES)
    else:
        base = _rand_name(r)
    return base + _maybe_ext(r)


def _compose_posix_path(r: random.Random) -> str:
    # Build a POSIX-like path with varying depth
    absolute = r.random() < 0.6
    depth = r.randint(0, 4)
    parts: List[str] = []
    for _ in range(depth):
        parts.append(_rand_component(r))
    # Decide file or directory end
    if r.random() < 0.8:
        parts.append(_rand_filename(r))
    else:
        parts.append(_rand_component(r))
    path = "/".join(p for p in parts if p != "")
    if absolute:
        path = "/" + path if not path.startswith("/") else path
    # Occasionally ensure directory path by trailing slash
    if r.random() < 0.2 and not path.endswith("/"):
        path = path + "/"
    return path or "/tmp/audit.log"


def _compose_windows_path(r: random.Random) -> str:
    drive = r.choice(WIN_DRIVES)
    depth = r.randint(0, 3)
    parts: List[str] = []
    for _ in range(depth):
        parts.append(_rand_component(r))
    parts.append(_rand_filename(r))
    # Join with backslashes
    path = drive + "\\".join(parts)
    return path


def _compose_mixed_path(r: random.Random) -> str:
    # Mix of relative and absolute with dot segments
    depth = r.randint(1, 5)
    parts = []
    for _ in range(depth):
        if r.random() < 0.3:
            parts.append("..")
        elif r.random() < 0.5:
            parts.append(".")
        else:
            parts.append(_rand_component(r))
    tail_file = r.random() < 0.9
    if tail_file:
        parts.append(_rand_filename(r))
    path = "/".join(parts)
    if r.random() < 0.5:
        path = "./" + path
    return path


def _decorate_for_api(r: random.Random, s: str) -> str:
    # For setParts expecting strings like "ABCFZ" or +/- forms, sometimes emit such strings
    # But since our generator is used for filename parameters primarily, keep as path.
    # Occasionally append filename-like prefixes used by AuditLog prefix API.
    if r.random() < 0.1:
        prefix = _rand_name(r, 1, 6)
        return prefix + "-" + s
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a strategy
    strat = r.random()
    if strat < 0.5:
        path = _compose_posix_path(r)
    elif strat < 0.7:
        path = _compose_windows_path(r)
    else:
        path = _compose_mixed_path(r)

    # Occasionally produce a directory path for setStorageDir use-cases
    if r.random() < 0.25:
        # ensure trailing separator on POSIX-like path
        if not (path.endswith("/") or path.endswith("\\")):
            path = path + "/"

    path = _decorate_for_api(r, path)

    # Ensure non-empty and reasonably short
    if not path:
        path = "/tmp/audit.log"
    if len(path) > 4000:
        path = path[:4000]

    # Return bytes without NUL; fuzzer/harness expects C string from this data blob
    return path.encode("utf-8", errors="ignore")
